CREATE OR REPLACE FUNCTION public.guard_roles() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.role='super_admin' AND (TG_OP='DELETE' OR NEW.role<>'super_admin') AND current_setting('club.transfer',true) IS DISTINCT FROM 'yes' THEN RAISE EXCEPTION 'Usa la transferencia protegida'; END IF; IF auth.uid() IS NOT NULL AND (coalesce(NEW.role,OLD.role) IN('directiva','super_admin') OR OLD.role IN('directiva','super_admin')) THEN IF current_setting('club.transfer',true) IS DISTINCT FROM 'yes' AND NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; IF coalesce(NEW.user_id,OLD.user_id)=auth.uid() AND current_setting('club.transfer',true) IS DISTINCT FROM 'yes' THEN RAISE EXCEPTION 'No puedes cambiar tus propios permisos'; END IF; END IF; RETURN coalesce(NEW,OLD); END $$;